<div id="satuan-modal" class="fixed inset-0 z-[100] hidden items-center justify-center bg-black/40 p-4"><div class="absolute inset-0" onclick="closeSatuanModal()"></div><div class="relative w-full max-w-xl rounded-xl bg-white shadow-2xl"><div class="flex justify-between border-b border-outline-variant px-6 py-4"><h2 id="satuan-title" class="text-xl font-semibold">Tambah Satuan Baru</h2><button type="button" onclick="closeSatuanModal()"><span class="material-symbols-outlined">close</span></button></div><form id="satuan-form" method="POST" action="{{ route('master-satuan.store') }}" class="space-y-4 p-6">@csrf<div><label class="mb-1 block font-semibold">Kode Satuan</label><input value="[otomatis]" readonly class="w-full rounded-md border border-outline-variant bg-surface-container-low px-3 py-2 text-on-surface-variant"></div><div><label class="mb-1 block font-semibold">Nama Satuan *</label><input id="satuan-nama" name="nm_master_satuan" required class="w-full rounded-md border border-outline-variant px-3 py-2"></div><div><label class="mb-1 block font-semibold">Deskripsi</label><textarea id="satuan-desc" name="desc_master_satuan" rows="3" class="w-full rounded-md border border-outline-variant px-3 py-2"></textarea></div><div><label class="mb-1 block font-semibold">Status *</label><select id="satuan-status" name="status_master_satuan" required class="w-full rounded-md border border-outline-variant px-3 py-2"><option>AKTIF</option><option>TIDAK AKTIF</option></select></div><div class="flex justify-end gap-2 border-t border-outline-variant pt-4"><button type="button" onclick="closeSatuanModal()" class="rounded-md border px-4 py-2">Batal</button><button class="rounded-md bg-primary px-5 py-2 font-label-bold text-on-primary">Simpan</button></div></form></div></div><script>function openSatuanModal(){const m=document.getElementById('satuan-modal');m.classList.remove('hidden');m.classList.add('flex');document.getElementById('satuan-title').textContent='Tambah Satuan Baru';document.getElementById('satuan-form').action='{{ route('master-satuan.store') }}';document.getElementById('satuan-form').querySelector('[name="_method"]')?.remove()}function closeSatuanModal(){const m=document.getElementById('satuan-modal');m.classList.add('hidden');m.classList.remove('flex')}function editSatuan(id,n,d,s){openSatuanModal();document.getElementById('satuan-title').textContent='Edit Satuan';document.getElementById('satuan-form').action='{{ url('/master-satuan') }}/'+id;let m=document.getElementById('satuan-form').querySelector('[name="_method"]');if(!m){m=document.createElement('input');m.type='hidden';m.name='_method';document.getElementById('satuan-form').prepend(m)}m.value='PUT';document.getElementById('satuan-nama').value=n||'';document.getElementById('satuan-desc').value=d||'';document.getElementById('satuan-status').value=s||'AKTIF'}</script>